// Deterministic setImmediate shim: drains a FIFO macrotask queue, no real timers.
globalThis.__q = [];
globalThis.setImmediate = (fn) => { globalThis.__q.push(fn); };
globalThis.__drain = () => { while (globalThis.__q.length) { const fn = globalThis.__q.shift(); fn(); } };

tasks.starter:
function processInChunks(items, chunkSize) {
  let total = 0;
  let start = 0;
  while (start < items.length) {
    const end = start + chunkSize;
    for (let i = start + 1; i < end; i++) {
      if (i < items.length) total += items[i];
    }
    // (a real impl would yield here via setImmediate between chunks)
    start = end;
  }
  return total;
}

