// called on every POST /resize
function resizeOffloaded(buf) {
  return new Promise((resolve, reject) => {
    const w = new Worker('./resize-worker.js');   // fresh worker per call
    w.postMessage(buf);                            // structured clone of the buffer
    w.on('message', (out) => resolve(out));
    w.on('error', reject);
  });
}
